CREATE TABLE my_org_domain_claims (tenant_id VARCHAR(64) NOT NULL, organization_id VARBINARY(255) NOT NULL, domain_id VARBINARY(255) NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,organization_id,domain_id), FOREIGN KEY (tenant_id,organization_id,domain_id) REFERENCES organization_discovery_domains(tenant_id,organization_id,id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
